def main():
    if not os.path.isfile("go.mod") or "module vpn-platform" not in open("go.mod", encoding="utf-8").read():
        sys.exit("ОСТАНОВКА: запустите скрипт из корня репозитория vpn_system")
    plan, problems = {}, []
    for path, find, repl in EDITS:
        s = plan.get(path)
        if s is None:
            if not os.path.isfile(path):
                problems.append(f"нет файла {path}"); continue
            s = open(path, encoding="utf-8").read()
        # Сначала «уже применено»: у части правок новый текст содержит старый
        # (функция добавляется рядом с существующим комментарием), и без этой
        # проверки повторный запуск вставил бы её второй раз.
        if repl in s:
            plan[path] = s
            print(f"  = уже применено: {path}")
            continue
        n = s.count(find)
        if n == 1:
            plan[path] = s.replace(find, repl)
        else:
            problems.append(f"{path}: фрагмент найден {n} раз")
    if problems:
        sys.exit("ОСТАНОВКА, ничего не изменено:\n  " + "\n  ".join(problems))
    for path, s in plan.items():
        open(path, "w", encoding="utf-8").write(s)
        print(f"  ✓ {path}")
    for path, body in NEW_FILES.items():
        os.makedirs(os.path.dirname(path), exist_ok=True)
        open(path, "w", encoding="utf-8").write(body)
        print(f"  ✓ {path} (записан целиком)")
    print("готово")

if __name__ == "__main__":
    main()
